  function createServiceIncomeGuide(calendar) {
    const factors2 = calendarFactors(calendar);
    return {
      version: 3,
      date: "2026-10-19",
      status: "working-guideline",
      moneyUnit: "Eisenpfennig",
      scope: "Orientierung f\xFCr Wachdienst in Gwynthor und seinem Umland, gut zahlenden Draig-Dienst und zahlungsf\xE4hige cenyrische Adelsh\xE4user. Keine universelle Soldordnung aller L\xE4nder und H\xE4user.",
      referenceMonthly: toMinor(referenceMonthlyCopper),
      baseMonthly: toMinor(referenceMonthlyCopper * martialSalaryMultiplier),
      salaryRevision: {
        id: "2026-10-19-martial-salary-v1",
        multiplier: martialSalaryMultiplier,
        incomeKind: "salary",
        militaryStatuses: ["ritter", "waffenknecht"]
      },
      watchGroups: structuredClone(WATCH_SERVICE_GROUPS),
      rules: [
        "Ausbildung, Familiensitz und Amt bilden keine durchgehende milit\xE4rische Rangfolge. Ein hoher Beamter kann wirtschaftlich anders stehen als ein Grafenangeh\xF6riger.",
        "Die Betr\xE4ge sind pers\xF6nliche Geldans\xE4tze vor individuellen Abgaben. Versorgung und Dienstausr\xFCstung werden separat vereinbart; gestellte Ausr\xFCstung wird kein pers\xF6nliches Verm\xF6gen.",
        "Die Geldsoldans\xE4tze f\xFCr Ritter und Waffenknechte einschlie\xDFlich der Amtsritter und beider Gardestufen wurden um 30 % erh\xF6ht. Ausbildungs- und Hauszuwendungen, gew\xF6hnliche Wachposten und hohe Beamte werden dadurch nicht automatisch erh\xF6ht. Die Revision ist einmal Bestandteil des Ansatzes und wird beim erneuten Lesen nicht nochmals aufgeschlagen.",
        "Bei mehreren Eigenschaften wird f\xFCr die tats\xE4chliche T\xE4tigkeit eine pers\xF6nliche Dienstbesoldung angesetzt. Hausrittersold und volle Amtsbesoldung werden nicht automatisch addiert.",
        "Dorfwache, Wachmann und Stadtwache werden nach zugewiesenem Gebiet und Tr\xE4ger unterschieden. Die Hausmacht dient pers\xF6nlich einem Adelshaus; die Stadtwache geh\xF6rt zur Stadt.",
        "Die Garde ist eine Auswahl f\xFCr besonderen Vertrauensdienst. Ritter und Waffenknechte behalten ihren unterschiedlichen Status. Gardesold ersetzt den entsprechenden gew\xF6hnlichen Sold und wird nicht vollst\xE4ndig darauf aufgeschlagen.",
        "Die Wachans\xE4tze gelten f\xFCr gew\xF6hnliche Vollzeitposten. F\xFChrung, besondere Verantwortung, Bereitschaft und Versorgungsumfang werden je Dienstvertrag gepr\xFCft. Private T\xFCrsteher, gewerbliche Wachleute und Gildens\xF6ldner erhalten dadurch keine automatische Zuordnung zur Stadtwache oder Hausmacht.",
        "Familienzuwendung, eigener Besitz und Amtseinkommen werden gesondert vereinbart. Es gibt keine automatische Addition aller Statusbetr\xE4ge; verarmte H\xE4user k\xF6nnen die vorgeschlagenen Zuwendungen unterschreiten.",
        "F\xFCr jedes Haus m\xFCssen die tats\xE4chlichen verf\xFCgbaren Einnahmen die Zuwendungen aller Angeh\xF6rigen tragen. Die gesamte Haus- oder Grafschaftskasse ist kein privates Einkommen.",
        "Auftr\xE4ge, Geschenke und Beute sind unregelm\xE4\xDFige Einnahmen und kein garantierter Bestandteil des Grundsoldes. Gekaufte Ausr\xFCstung wird nicht monatlich erneut angeschafft."
      ],
      roles: roles.map((role) => {
        const multiplier = usesMartialSalary(role) ? martialSalaryMultiplier : 1;
        const moneyAt = (factor2) => toMinor(referenceMonthlyCopper * factor2 * multiplier);
        const monthly = moneyAt(role.factor);
        const [min, max] = role.range || [role.factor, role.factor];
        const { factor, range, ...description } = role;
        return {
          group: "training-noble-office",
          ...description,
          monthly,
          monthlyMin: moneyAt(min),
          monthlyMax: moneyAt(max),
          weekly: Math.round(monthly / factors2.weeksPerMonth),
          annual: monthly * factors2.monthsPerYear
        };
      })
    };
  }

