  function renderHouseholdSelector() {
    return `<div class="economy-household-controls"><label class="economy-field"><span>Beispielhaushalt</span><select data-economy-household="profile">${HOUSEHOLD_PROFILES.map((p) => `<option value="${p.id}">${escape(p.title)}</option>`).join("")}</select></label>
    <label class="economy-field"><span>Ertragsfaktor</span><input type="number" min="0" max="10" step="0.05" value="1" data-economy-household="incomeFactor"></label>
    <label class="economy-field"><span>Kostenfaktor</span><input type="number" min="0" max="10" step="0.05" value="1" data-economy-household="costFactor"></label>
    <label class="economy-check"><input type="checkbox" data-economy-household="churchEnabled">10 % Kirchenbeitrag auf positiven Rest nach Unterhalt</label></div><div data-economy-household-result></div>`;
  }
  function renderHousehold(profile, calendar, controls) {
    const r = calculateHousehold(profile, calendar, controls);
    const assetRows = profile.assets.map((row2) => `<tr><th scope="row">${escape(row2.label)}</th><td>${money(Math.round(row2.cash * 100))}</td></tr>`).join("");
    const lines = (rows, factor) => rows.map((row2) => `<tr><th scope="row">${escape(row2.label)}</th><td>${money(Math.round(row2.cash * factor * 100))}</td><td>${money(Math.round(row2.inKind * factor * 100))}</td></tr>`).join("");
    const comparisons = HOUSEHOLD_PROFILES.map((p) => {
      const c = calculateHousehold(p, calendar);
      return `<tr><th scope="row">${escape(p.title)}</th><td>${money(c.incomeCash)}</td><td class="${signedClass(c.netCashWeek)}">${money(c.netCashWeek)}</td><td>${money(c.cash)}</td><td>${money(c.netWorth)}</td></tr>`;
    }).join("");
    return `<h3>${escape(profile.title)}</h3><p>${escape(profile.household)}</p>${info("Alle Haushalte sind ausdr\xFCcklich erfundene Rechenbeispiele f\xFCr Cenyr, keine allgemeinen Einkommensgesetze und keine Zuordnung zu bestehenden Familien.")}
    <div class="economy-metrics">${[["Geldeinnahmen pro Jahr", r.incomeCash], ["Restgeld pro Neuntagewoche", r.netCashWeek], ["Geld in der Truhe", r.cash], ["Nettoverm\xF6gen \xB7 Rechenwert", r.netWorth]].map(([label, value]) => `<div class="economy-metric"><span>${label}</span><strong class="${signedClass(value)}">${money(value)}</strong></div>`).join("")}</div>
    <div class="economy-ledger-columns"><section><h4>J\xE4hrliche Einnahmen</h4>${table(["Herkunft", "Geld", "Naturalienwert"], lines(profile.income, Number(controls.incomeFactor ?? 1)), "Haushaltseinnahmen")}</section>
      <section><h4>J\xE4hrliche Ausgaben und Unterhalt</h4>${table(["Verwendung", "Geld", "Naturalienwert"], lines(profile.costs, Number(controls.costFactor ?? 1)), "Haushaltskosten")}</section></div>
    ${info(profile.note)}${info(r.note)}
    <p class="economy-note">Naturalien-Zukauf bei Unterdeckung: <strong>${money(r.naturalShortfall)}</strong> pro Jahr \xB7 verbleibende Naturalreserve: <strong>${money(r.netKindYear)}</strong> \xB7 optionaler Kirchenbeitrag: <strong>${money(r.church)}</strong>.</p>
    <details><summary>Angenommener Besitz und Schulden</summary>${table(["Besitz", "Rechenwert"], assetRows + `<tr><th scope="row">Schulden</th><td>\u2212${money(r.debt)}</td></tr><tr class="economy-total-row"><th scope="row">Nettoverm\xF6gen</th><td>${money(r.netWorth)}</td></tr>`, "Verm\xF6gensrechnung")}${info("Verm\xF6genswerte sind Sch\xE4tzans\xE4tze. Der Rang allein erzeugt kein Verm\xF6gen; Landpacht ist beim Bauern kein eigener Landbesitz. Schulden, politische Rechte und schwer ver\xE4u\xDFerliche Ausr\xFCstung sind von Bargeld zu unterscheiden.")}</details>
    ${renderServiceIncomeGuide(calendar)}
    <details><summary>Alle sechs Ausgangsprofile vergleichen</summary>${table(["Haushalt", "Geldeinnahmen / Jahr", "Restgeld / Woche", "Bargeld", "Nettoverm\xF6gen"], comparisons, "Vergleich von Bauern, B\xFCrgern und Adel")}${info(`Ein Jahr hat ${r.factors.daysPerYear} Tage und ${numberText(r.factors.weeksPerYear)} Neuntagewochen. Die Wochenwerte gl\xE4tten Ernten, Soldtermine und unregelm\xE4\xDFige Abgaben.`)}</details>`;
  }

